function Read-JsonFile {
param([Parameter(Mandatory)][string]$Path)
Get-Content -LiteralPath $Path -Raw -Encoding UTF8 | ConvertFrom-Json -Depth 100
}

function Write-JsonFile {
param(
[Parameter(Mandatory)][string]$Path,
[Parameter(Mandatory)]$Object
)
$json = $Object | ConvertTo-Json -Depth 100
Set-Content -LiteralPath $Path -Value ($json + [Environment]::NewLine) -Encoding UTF8
}

function Add-UniqueItems {
param(
[Parameter(Mandatory)]$Array,
[Parameter(Mandatory)][string[]]$Items
)

$list = [System.Collections.Generic.List[object]]::new()
foreach ($item in @($Array)) {
    if ($null -ne $item) { $list.Add($item) }
}

foreach ($item in $Items) {
    if ($list -notcontains $item) {
        $list.Add($item)
    }
}

return @($list)

}

function Get-Collection {
param(
[Parameter(Mandatory)]$Root,
[Parameter(Mandatory)][string[]]$CandidateNames
)

if ($Root -is [array]) {
    return @{
        Parent = $null
        Name = $null
        Items = @($Root)
        IsRootArray = $true
    }
}

foreach ($name in $CandidateNames) {
    if ($Root.PSObject.Properties.Name -contains $name) {
        return @{
            Parent = $Root
            Name = $name
            Items = @($Root.$name)
            IsRootArray = $false
        }
    }
}

return @{
    Parent = $Root
    Name = $CandidateNames[0]
    Items = @()
    IsRootArray = $false
}

}

function Set-Collection {
param(
[Parameter(Mandatory)]$Root,
[Parameter(Mandatory)]$CollectionInfo,
[Parameter(Mandatory)]$Items
)

if ($CollectionInfo.IsRootArray) {
    return @($Items)
}

if ($CollectionInfo.Parent.PSObject.Properties.Name -contains $CollectionInfo.Name) {
    $CollectionInfo.Parent.$($CollectionInfo.Name) = @($Items)
}
else {
    $CollectionInfo.Parent | Add-Member -NotePropertyName $CollectionInfo.Name -NotePropertyValue @($Items)
}

return $Root

}

function Add-CapabilityIntents {
param(
[Parameter(Mandatory)]$Capabilities,
[Parameter(Mandatory)][string]$Id,
[Parameter(Mandatory)][string[]]$Intents
)

$collection = Get-Collection -Root $Capabilities -CandidateNames @("capabilities", "items")
$items = @($collection.Items)

foreach ($cap in $items) {
    if ($cap.id -eq $Id) {
        if ($cap.PSObject.Properties.Name -notcontains "intents" -or $null -eq $cap.intents) {
            $cap | Add-Member -NotePropertyName "intents" -NotePropertyValue @()
        }
        $cap.intents = Add-UniqueItems -Array $cap.intents -Items $Intents
        break
    }
}

return Set-Collection -Root $Capabilities -CollectionInfo $collection -Items $items

}

function Add-Route {
param(
[Parameter(Mandatory)]$Routes,
[Parameter(Mandatory)]$Route
)

$collection = Get-Collection -Root $Routes -CandidateNames @("routes", "items")
$items = [System.Collections.Generic.List[object]]::new()

foreach ($item in @($collection.Items)) {
    if ($item.id -ne $Route.id) {
        $items.Add($item)
    }
}

$items.Add($Route)

return Set-Collection -Root $Routes -CollectionInfo $collection -Items @($items)

}

