function Install-AiFindPreflightBlock {
param([Parameter(Mandatory)][string]$Path)

$content = Get-Content -LiteralPath $Path -Raw -Encoding UTF8

if ($content -notmatch "(?m)^\s*param\s*\(") {
    throw "ai.ps1 must have a top-level param() block."
}

if ($content -notmatch "\[switch\]\s*\$Json") {
    $content = [regex]::Replace(
        $content,
        "(?s)(^\s*param\s*\()(.*?)(\)\s*)",
        {
            param($m)

            $body = $m.Groups[2].Value
            $prefix = $m.Groups[1].Value
            $suffix = $m.Groups[3].Value

            if ($body.Trim().Length -eq 0) {
                return "$prefix`n    [switch]`$Json`n$suffix"
            }

            $trimmed = $body.TrimEnd()
            if ($trimmed.EndsWith(",")) {
                return "$prefix$trimmed`n    [switch]`$Json`n$suffix"
            }

            return "$prefix$trimmed,`n    [switch]`$Json`n$suffix"
        },
        1
    )
}

