function Test-AiTextMatch {
param(
[Parameter(Mandatory)][string]$Text,
[AllowNull()]$Patterns
)

foreach ($pattern in @($Patterns)) {
    if ($null -eq $pattern) { continue }

    $p = [string]$pattern
    if ([string]::IsNullOrWhiteSpace($p)) { continue }

    if ($Text.IndexOf($p, [StringComparison]::OrdinalIgnoreCase) -ge 0) {
        return $true
    }
}

return $false

}

function Find-AiRealEntryPoint {
param([Parameter(Mandatory)][string]$Task)

$routesRoot = Read-AiRegistryJson -Name "routes.json"
$capsRoot = Read-AiRegistryJson -Name "capabilities.json"

$routes = Get-AiCollection -Root $routesRoot -Names @("routes", "items")
$caps = Get-AiCollection -Root $capsRoot -Names @("capabilities", "items")

$routeMatch = $null
$capMatch = $null

foreach ($route in $routes) {
    $match = $route.match
    if ($null -eq $match) { continue }

    $matched = $false
    foreach ($prop in @("taskKinds", "intents", "keywords", "patterns")) {
        if ($match.PSObject.Properties.Name -contains $prop) {
            if (Test-AiTextMatch -Text $Task -Patterns $match.$prop) {
                $matched = $true
                break
            }
        }
    }

    if ($matched) {
        $routeMatch = $route
        break
    }
}

foreach ($cap in $caps) {
    $matched = $false

    foreach ($prop in @("intents", "taskKinds", "keywords", "patterns")) {
        if ($cap.PSObject.Properties.Name -contains $prop) {
            if (Test-AiTextMatch -Text $Task -Patterns $cap.$prop) {
                $matched = $true
                break
            }
        }
    }

    if ($matched) {
        $capMatch = $cap
        break
    }
}

if ($null -eq $routeMatch -and $null -eq $capMatch) {
    return [pscustomobject]@{
        matched = $false
        primary = $null
        primaryName = $null
        fallback = $null
        route = $null
        requiredSteps = @()
        requiredSkills = @()
        confidence = "none"
    }
}

$primary = $null
$primaryName = $null
$fallback = $null
$requiredSteps = @()
$requiredSkills = @()

if ($null -ne $routeMatch) {
    if ($routeMatch.PSObject.Properties.Name -contains "primary") {
        $primary = $routeMatch.primary
    }

    if ($routeMatch.PSObject.Properties.Name -contains "fallback") {
        $fallback = $routeMatch.fallback
    }

    if ($routeMatch.PSObject.Properties.Name -contains "requiredSteps") {
        $requiredSteps = @($routeMatch.requiredSteps)
    }
}

if ($null -ne $capMatch) {
    if ($capMatch.PSObject.Properties.Name -contains "model" -and -not $primary) {
        $primary = $capMatch.model
    }

    if ($capMatch.PSObject.Properties.Name -contains "primary" -and -not $primary) {
        $primary = $capMatch.primary
    }

    if ($capMatch.PSObject.Properties.Name -contains "requiredSkills") {
        $requiredSkills = @($capMatch.requiredSkills)
    }

    if ($capMatch.PSObject.Properties.Name -contains "skills" -and $requiredSkills.Count -eq 0) {
        $requiredSkills = @($capMatch.skills)
    }
}

if ($primary) {
    $primaryName = [string]$primary
}

$confidence = if ($null -ne $routeMatch -and $null -ne $capMatch) {
    "high"
}
elseif ($null -ne $routeMatch -or $null -ne $capMatch) {
    "medium"
}
elseif ($primary -or $fallback) {
    "low"
}
else {
    "none"
}

[pscustomobject]@{
    matched = $true
    primary = $primary
    primaryName = $primaryName
    fallback = $fallback
    route = if ($null -ne $routeMatch) { $routeMatch.id } else { $null }
    requiredSteps = @($requiredSteps)
    requiredSkills = @($requiredSkills)
    confidence = $confidence
}

}

function Invoke-AiFind {
param(
[Parameter(Mandatory)][string]$Task,
[switch]$Json
)

$result = Find-AiRealEntryPoint -Task $Task

if ($Json) {
    ConvertTo-AiJson -Value $result
    if (-not $result.matched) { exit 2 }
    return
}

if (-not $result.matched) {
    Write-Host "No matching route/capability found."
    exit 2
}

Write-Host "Matched: $($result.matched)"
Write-Host "Primary: $($result.primary)"
Write-Host "PrimaryName: $($result.primaryName)"
Write-Host "Fallback: $($result.fallback)"
Write-Host "Route: $($result.route)"
Write-Host "RequiredSteps: $(@($result.requiredSteps) -join ', ')"
Write-Host "RequiredSkills: $(@($result.requiredSkills) -join ', ')"
Write-Host "Confidence: $($result.confidence)"

}

function Invoke-AiPreflight {
param([Parameter(Mandatory)][string]$Task)

$registryOk = Test-Path -LiteralPath "D:\Code\ai-infra\registry"
if (-not $registryOk) {
    Write-Error "Registry check failed."
    exit 1
}

$findOutput = & $PSCommandPath find --json $Task
$findExit = $LASTEXITCODE

if ($findExit -ne 0) {
    Write-Error "Find failed."
    exit $findExit
}

$find = $findOutput | ConvertFrom-Json -Depth 50

Write-Host "Matched: $($find.matched)"
Write-Host "Primary: $($find.primary)"
Write-Host "PrimaryName: $($find.primaryName)"
Write-Host "Fallback: $($find.fallback)"
Write-Host "Route: $($find.route)"
Write-Host "RequiredSteps: $(@($find.requiredSteps) -join ', ')"
Write-Host "RequiredSkills: $(@($find.requiredSkills) -join ', ')"
Write-Host "Confidence: $($find.confidence)"

if (-not $find.matched) {
    Write-Error "No matching route/capability found."
    exit 2
}

$serviceOk = $true

if (Get-Command Test-AiService -ErrorAction SilentlyContinue) {
    $serviceOk = [bool](Test-AiService)
}

if (-not $serviceOk) {
    Write-Error "Service check failed."
    exit 1
}

if ($registryOk -and $find.matched) {
    $env:PREFLIGHT_TOKEN = [guid]::NewGuid().ToString("N")
    Write-Host "PREFLIGHT_TOKEN=$env:PREFLIGHT_TOKEN"
}

}
